<?php
declare(strict_types=1);

function course_domain_available(PDO $db): bool {return (bool)$db->query("SELECT 1 FROM sqlite_master WHERE type='table' AND name='courses'")->fetchColumn();}
function course_by_id(PDO $db,int $courseId): ?array {$q=$db->prepare("SELECT * FROM courses WHERE id=? AND status!='archived' LIMIT 1");$q->execute([$courseId]);return $q->fetch()?:null;}
function course_list(PDO $db,?int $activityId=null): array {$sql="SELECT c.*,p.title public_page_title,p.slug public_page_slug,f.title registration_form_title,f.form_key registration_form_key FROM courses c LEFT JOIN cms_pages p ON p.id=c.public_page_id LEFT JOIN cms_forms f ON f.id=c.registration_form_id WHERE c.status!='archived'";$args=[];if($activityId!==null){$sql.=' AND c.activity_id=?';$args[]=$activityId;}$sql.=' ORDER BY c.title COLLATE NOCASE,c.id';$q=$db->prepare($sql);$q->execute($args);return $q->fetchAll();}
function course_by_public_page(PDO $db,int $pageId): ?array {$q=$db->prepare("SELECT * FROM courses WHERE public_page_id=? AND status!='archived' LIMIT 1");$q->execute([$pageId]);return $q->fetch()?:null;}
function course_by_registration_form(PDO $db,int $formId): array {$q=$db->prepare("SELECT * FROM courses WHERE registration_form_id=? AND status!='archived' ORDER BY id");$q->execute([$formId]);return $q->fetchAll();}
function course_slug_unique(PDO $db,int $activityId,string $slug,int $ignoreId=0): string {$base=activity_slug($slug);if($base==='')$base='curso';$candidate=$base;$n=2;while(true){$q=$db->prepare('SELECT id FROM courses WHERE activity_id=? AND slug=?'.($ignoreId>0?' AND id!=?':''));$args=[$activityId,$candidate];if($ignoreId>0)$args[]=$ignoreId;$q->execute($args);if(!$q->fetchColumn())return $candidate;$candidate=$base.'-'.$n++;}}
function course_create_from_page(PDO $db,int $pageId,int $registrationFormId=0): array {
    $page=cms_page_by_id($db,$pageId)??throw new RuntimeException('Página do curso não encontrada.');if((string)$page['status']==='archived')throw new RuntimeException('A página do curso está arquivada.');if(course_by_public_page($db,$pageId))throw new RuntimeException('Esta página já está associada a um curso.');
    $activityId=(int)$page['activity_id'];$form=null;if($registrationFormId>0){$form=cms_form_by_id($db,$registrationFormId);if(!$form||(int)$form['activity_id']!==$activityId||(string)$form['status']==='archived'||cms_form_purpose($form)!=='enrollment')throw new RuntimeException('Escolha um formulário de inscrição válido deste site.');}
    $now=utc_now();$slug=course_slug_unique($db,$activityId,(string)$page['slug']);$db->prepare("INSERT INTO courses(course_uuid,activity_id,title,slug,status,public_page_id,registration_form_id,created_at,updated_at) VALUES(?,?,?,?, 'active',?,?,?,?)")->execute([student_uuid(),$activityId,trim((string)$page['title'])?:'Curso',$slug,$pageId,$form?(int)$form['id']:null,$now,$now]);return course_by_id($db,(int)$db->lastInsertId())??throw new RuntimeException('course_create_failed');
}
function course_update(PDO $db,int $courseId,array $input): array {
    $course=course_by_id($db,$courseId)??throw new RuntimeException('Curso não encontrado.');$activityId=(int)$course['activity_id'];$title=trim((string)($input['title']??$course['title']));if($title==='')throw new RuntimeException('Informe o nome do curso.');$slug=course_slug_unique($db,$activityId,(string)($input['slug']??$course['slug']),$courseId);
